import os
import json
from typing import Any, Dict, List, Union

import boto3


def extract_layout(document_bytes_or_path: Union[str, bytes, bytearray], analyze_features: List[str] = None) -> Dict[str, Any]:
    """
    Extract OCR/layout elements from a document using Amazon Textract.

    Returns a dictionary containing:
      - blocks: all Textract blocks
      - lines: extracted line texts with geometry and confidence
      - tables: extracted table cells by table
      - key_values: extracted key-value pairs
    """
    if analyze_features is None:
        analyze_features = ["TABLES", "FORMS"]

    textract = boto3.client("textract")

    if isinstance(document_bytes_or_path, (bytes, bytearray)):
        document_bytes = bytes(document_bytes_or_path)
    elif isinstance(document_bytes_or_path, str):
        with open(document_bytes_or_path, "rb") as f:
            document_bytes = f.read()
    else:
        raise TypeError("document_bytes_or_path must be a file path, bytes, or bytearray")

    response = textract.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=analyze_features,
    )

    blocks = response.get("Blocks", [])
    block_map = {b.get("Id"): b for b in blocks if b.get("Id")}

    lines = []
    tables = []
    key_values = []

    for block in blocks:
        block_type = block.get("BlockType")

        if block_type == "LINE":
            lines.append(
                {
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "geometry": block.get("Geometry", {}),
                    "page": block.get("Page"),
                    "id": block.get("Id"),
                }
            )

        elif block_type == "KEY_VALUE_SET" and "KEY" in block.get("EntityTypes", []):
            key_text = _collect_text_from_relationships(block, block_map, child_types={"WORD"})
            value_text = ""
            for rel in block.get("Relationships", []):
                if rel.get("Type") == "VALUE":
                    for value_id in rel.get("Ids", []):
                        value_block = block_map.get(value_id, {})
                        value_text = _collect_text_from_relationships(value_block, block_map, child_types={"WORD"})
            key_values.append(
                {
                    "key": key_text,
                    "value": value_text,
                    "page": block.get("Page"),
                    "confidence": block.get("Confidence"),
                    "id": block.get("Id"),
                }
            )

        elif block_type == "TABLE":
            tables.append(_extract_table(block, block_map))

    return {
        "blocks": blocks,
        "lines": lines,
        "tables": tables,
        "key_values": key_values,
        "raw_response": response,
    }


def _collect_text_from_relationships(
    block: Dict[str, Any],
    block_map: Dict[str, Dict[str, Any]],
    child_types: set = None,
) -> str:
    if child_types is None:
        child_types = {"WORD", "SELECTION_ELEMENT"}

    texts = []
    for rel in block.get("Relationships", []):
        if rel.get("Type") != "CHILD":
            continue
        for child_id in rel.get("Ids", []):
            child = block_map.get(child_id, {})
            if child.get("BlockType") not in child_types:
                continue
            if child.get("BlockType") == "WORD":
                texts.append(child.get("Text", ""))
            elif child.get("BlockType") == "SELECTION_ELEMENT":
                if child.get("SelectionStatus") == "SELECTED":
                    texts.append("X")
    return " ".join(t for t in texts if t).strip()


def _extract_table(table_block: Dict[str, Any], block_map: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
    cell_blocks = []
    for rel in table_block.get("Relationships", []):
        if rel.get("Type") == "CHILD":
            for cid in rel.get("Ids", []):
                cell = block_map.get(cid, {})
                if cell.get("BlockType") == "CELL":
                    cell_blocks.append(cell)

    if not cell_blocks:
        return {
            "page": table_block.get("Page"),
            "cells": [],
            "rows": [],
            "id": table_block.get("Id"),
        }

    max_row = max(cell.get("RowIndex", 0) for cell in cell_blocks)
    max_col = max(cell.get("ColumnIndex", 0) for cell in cell_blocks)

    rows = [["" for _ in range(max_col)] for _ in range(max_row)]
    cells = []

    for cell in cell_blocks:
        row_idx = cell.get("RowIndex", 1) - 1
        col_idx = cell.get("ColumnIndex", 1) - 1
        text = _collect_text_from_relationships(cell, block_map, child_types={"WORD", "SELECTION_ELEMENT"})
        rows[row_idx][col_idx] = text
        cells.append(
            {
                "row": cell.get("RowIndex"),
                "column": cell.get("ColumnIndex"),
                "row_span": cell.get("RowSpan"),
                "column_span": cell.get("ColumnSpan"),
                "text": text,
                "confidence": cell.get("Confidence"),
                "geometry": cell.get("Geometry", {}),
                "id": cell.get("Id"),
            }
        )

    return {
        "page": table_block.get("Page"),
        "id": table_block.get("Id"),
        "cells": cells,
        "rows": rows,
    }


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Extract OCR/layout elements from a document using Amazon Textract.")
    parser.add_argument("document", help="Path to a local document file (PDF/image).")
    parser.add_argument("--features", nargs="*", default=["TABLES", "FORMS"], help="Textract feature types.")
    args = parser.parse_args()

    result = extract_layout(args.document, analyze_features=args.features)
    print(json.dumps(result, indent=2, default=str))
